import json, os
S=os.getcwd(); css=open("base.css").read(); word=open("word.html").read()
BG="background:radial-gradient(120% 70% at 85% 0%,#163a2a 0%,#0b1626 55%,#07101c 100%)"
def page(w,h,body): return f"<!doctype html><html><head><meta charset=utf-8><style>{css}</style></head><body><div class='c' style='width:{w}px;height:{h}px'>{body}</div></body></html>"
def img(n,style=""): return f'<img src="file://{S}/{n}" style="{style}">'
jobs=[]
def add(out,w,h,body,tr=False): jobs.append(dict(w=w,h=h,out=out,transparent=tr,html=page(w,h,body)))
WIN="display:block;width:100%;border-radius:22px;box-shadow:0 40px 80px -30px #000"
# ---------- 30 Nov reel overlays ----------
add("ov/r30-a.png",1080,1920,'<div style="position:absolute;left:0;right:0;top:0;height:640px;background:linear-gradient(#07101cee,#07101c00)"></div><p style="position:absolute;left:90px;right:90px;top:260px;text-align:center;font:600 96px/1.06 F;text-shadow:0 4px 30px #000a">Years of paper logbook.</p>',True)
add("ov/r30-b.png",1080,1920,'<p style="position:absolute;left:80px;right:80px;top:330px;text-align:center;font:600 84px/1.08 F">One photo per page.</p><p style="position:absolute;left:80px;right:80px;bottom:420px;text-align:center;font:600 46px/1.25 M;color:#c9d4e2">Every line read, checked,<br>and totalled for you.</p>',True)
add("ov/r30-c.png",1080,1920,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:0;right:0;top:560px;display:flex;justify-content:center;transform:scale(1.5)">{word}</div><p style="position:absolute;left:80px;right:80px;top:760px;text-align:center;font:600 64px/1.15 F">Also Excel, CSV,<br>LogTen, Safelog,<br>CrewLounge.</p><p class="mono green" style="position:absolute;left:0;right:0;top:1180px;text-align:center;font-size:96px;font-weight:700">15.12</p><p style="position:absolute;left:0;right:0;top:1320px;text-align:center;font-size:40px;color:#c9d4e2">30 days free · no card</p>')
# ---------- 1 Dec LinkedIn PDF carousel (1080x1350) ----------
def li(n,title,body,foot=True):
    add(f"out/li-0112-doc-{n}.png",1080,1350,f'<div style="position:absolute;inset:0;{BG}"></div><div style="position:absolute;left:84px;top:84px;transform:scale(.8);transform-origin:left top">{word}</div><p class="mono" style="position:absolute;right:84px;top:92px;font-size:22px;color:#93a6bc">{n} / 6</p><div style="position:absolute;left:84px;right:84px;top:230px"><h2 style="font:600 76px/1.05 F;letter-spacing:-.015em">{title}</h2>{body}</div>')
li(1,"Your old logbook, imported in minutes",'<p style="font-size:38px;line-height:1.4;color:#c9d4e2;margin-top:34px">Switching logbooks usually means a weekend of retyping. It shouldn\'t.</p><div style="margin-top:70px;display:flex;flex-wrap:wrap;gap:16px">'+"".join(f'<span style="border:2px solid #ffffff2a;border-radius:999px;padding:14px 26px;font:700 30px M">{x}</span>' for x in ["Excel & CSV","LogTen","Safelog","CrewLounge","Roster PDF","Photo of a paper page"])+'</div><p style="position:absolute;right:0;top:880px;font:700 32px M;color:#4ade80">Swipe →</p>')
li(2,"Excel and CSV exports",'<p style="font-size:38px;line-height:1.4;color:#c9d4e2;margin-top:34px">Drop the file: Geardown recognises the columns (date, route, times, functions, landings), even when they are named differently.</p>'+'<div style="margin-top:60px;border:2px solid #ffffff22;border-radius:18px;overflow:hidden;font:500 26px J">'+"".join(f'<div style="display:grid;grid-template-columns:1.1fr 1fr 1fr 1fr;padding:14px 20px;{"background:#ffffff10;color:#93a6bc;font-size:22px" if i==0 else "border-top:1px solid #ffffff14"}"><span>{a}</span><span>{b}</span><span>{c}</span><span>{d}</span></div>' for i,(a,b,c,d) in enumerate([("DATE","FROM","TO","TOTAL"),("21/11","LSGG","LEMD","2:04"),("21/11","EGLL","LSGG","1:39"),("20/11","LSGG","EGLL","1:36")]))+'</div>')
li(3,"LogTen, Safelog, CrewLounge",'<p style="font-size:38px;line-height:1.4;color:#c9d4e2;margin-top:34px">Export from your current app and import the file as it is. Night, IFR, PIC and multi-pilot time come across column by column.</p>')
li(4,"A photo of your paper logbook",f'<p style="font-size:38px;line-height:1.4;color:#c9d4e2;margin-top:34px">One photo per page. Every line is read and checked.</p><div style="margin-top:50px">{img("win-import.png",WIN)}</div>')
li(5,"You check the totals first",'<p style="font-size:38px;line-height:1.4;color:#c9d4e2;margin-top:34px">Before anything is saved, Geardown shows the totals it found, so you can compare them with your last page. You can cancel an import at any time.</p><p style="font-size:38px;line-height:1.4;color:#c9d4e2;margin-top:30px">And your logbook stays yours: export everything again whenever you want, in EASA, FAA or CASA layouts.</p>')
